/* Dark SaaS — near-black canvas, subtle borders, one electric accent, tight type */
.theme-dark-saas {
  --bg: oklch(0.139 0.003 246.3);
  --surface: oklch(0.2 0.005 285);
  --surface-2: oklch(0.24 0.006 285);
  --fg: oklch(0.97 0.002 285);
  --fg-muted: oklch(0.649 0.015 262.4);
  --accent: oklch(0.62 0.23 274);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.72 0.15 200);
  --line: oklch(1 0 0 / 10%);
  --success: oklch(0.7 0.17 155);
  --warning: oklch(0.78 0.16 80);
  --danger: oklch(0.63 0.22 22);

  --radius: 0.5rem;
  --radius-sm: 0.375rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px 0 oklch(0 0 0 / 45%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 65%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 75%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Inter", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.035em;
  --label-transform: none;
  --label-tracking: 0em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-dark-saas h1,
.theme-dark-saas h2,
.theme-dark-saas h3 {
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

/* signature */
.theme-dark-saas { --font-ui: var(--font-display); }
.theme-dark-saas h1 { background: linear-gradient(180deg, var(--fg), var(--fg-muted)); -webkit-background-clip: text; background-clip: text; color: transparent; letter-spacing: -0.045em; }

/* alt mode: auto-derived light variant */
.theme-dark-saas.alt-mode {
  --bg: oklch(0.98 0.003 246.3);
  --surface: oklch(0.955 0.003 246.3);
  --surface-2: oklch(0.92 0.003 246.3);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
}

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
